最近的对话：
{{ recent|join('\n') }}

{% endif -%}
{%- if asset_lines %}
上传的文件（按上传顺序）：
{{ asset_lines|join('\n') }}
{%- endif %}
{%- if material_pending_line %}
{{ material_pending_line }}
